#[test]
fn newtons_per_cubic_millimeter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 1000000000.0;
        assert_close(
            SpecificWeight::from_newtons_per_cubic_millimeter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x * 0.000000001;
        assert_close(
            SpecificWeight::from_base(base).as_newtons_per_cubic_millimeter(),
            back,
            F64_TOL,
        );
        assert_close(
            SpecificWeight::from_newtons_per_cubic_millimeter(v).as_newtons_per_cubic_millimeter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            SpecificWeight::from_newtons_per_cubic_millimeter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            SpecificWeight::from_base(base as f32).as_newtons_per_cubic_millimeter() as f64,
            back,
            F32_TOL,
        );
    }
}

